INSERT INTO clues (dish_id, order_index, text) VALUES
((SELECT id FROM dishes WHERE slug='eggplant-parmesan'), 1, 'A layered bake you cut in squares, still bubbling at the edges.'),
((SELECT id FROM dishes WHERE slug='eggplant-parmesan'), 2, 'Campania, Sicily and Parma all claim it, and a Naples cookbook printed the tomato version in 1837.'),
((SELECT id FROM dishes WHERE slug='eggplant-parmesan'), 3, 'Sicilian writers say the overlapping slices look like the slats of a shutter, and that gave it its name.'),
((SELECT id FROM dishes WHERE slug='eggplant-parmesan'), 4, 'You fry thin slices until golden, then layer them with tomato sauce, mozzarella and basil and bake.'),
((SELECT id FROM dishes WHERE slug='eggplant-parmesan'), 5, 'Fried vegetable slices layered with tomato sauce and melting cheese, Italy''s original parmigiana.'),
((SELECT id FROM dishes WHERE slug='penne-alla-vodka'), 1, 'Pink, creamy, and clinging to ridged tubes of pasta.'),
((SELECT id FROM dishes WHERE slug='penne-alla-vodka'), 2, 'A restaurant in Bologna and a New York chef both claim it, and an actor''s 1974 cookbook printed it first.'),
((SELECT id FROM dishes WHERE slug='penne-alla-vodka'), 3, 'In the 1980s it was what Italians and Americans ordered after a night at the disco.'),
((SELECT id FROM dishes WHERE slug='penne-alla-vodka'), 4, 'You simmer tomato with onion, stir in cream until the sauce turns pink, and finish it with parmesan.'),
((SELECT id FROM dishes WHERE slug='penne-alla-vodka'), 5, 'Short quills in a blush tomato and cream sauce, an Italian dish New York claims too.'),
((SELECT id FROM dishes WHERE slug='pesto-pasta'), 1, 'Bright green sauce that you never cook, just toss with the drained pasta.'),
((SELECT id FROM dishes WHERE slug='pesto-pasta'), 2, 'Genoese cooks pounded it in marble mortars, and an 1863 cookbook made basil the base.'),
((SELECT id FROM dishes WHERE slug='pesto-pasta'), 3, 'The Ligurian way adds boiled potatoes and green beans to the same pot as the pasta.'),
((SELECT id FROM dishes WHERE slug='pesto-pasta'), 4, 'You crush basil, pine nuts, garlic and coarse salt with a pestle, then work in grated cheese and olive oil.'),
((SELECT id FROM dishes WHERE slug='pesto-pasta'), 5, 'Italy''s Genoese basil sauce, bright green and tossed through pasta with pine nuts and cheese.'),
((SELECT id FROM dishes WHERE slug='biscotti'), 1, 'Hard, dry fingers made for dunking, or they''ll crack a tooth.'),
((SELECT id FROM dishes WHERE slug='biscotti'), 2, 'Roman legions carried twice-baked bread, and a Prato baker revived this almond recipe in the 1800s.'),
((SELECT id FROM dishes WHERE slug='biscotti'), 3, 'Tuscans dunk them in Vin Santo, a sweet dessert wine, at the end of a meal.'),
((SELECT id FROM dishes WHERE slug='biscotti'), 4, 'You bake an almond dough as one log, slice it on the diagonal, and bake the slices again until bone dry.'),
((SELECT id FROM dishes WHERE slug='biscotti'), 5, 'Long, crunchy almond biscuits baked twice in Prato, Italy, and dipped in coffee or sweet wine.'),
((SELECT id FROM dishes WHERE slug='macarons'), 1, 'Pastel rounds lined up by colour in a pastry-shop window.'),
((SELECT id FROM dishes WHERE slug='macarons'), 2, 'Nuns in Nancy sold plain ones in the 1790s, and Paris bakers sandwiched them with filling in the 1930s.'),
((SELECT id FROM dishes WHERE slug='macarons'), 3, 'Each shell needs a ruffled foot around its base, and bakers judge a batch by it.'),
((SELECT id FROM dishes WHERE slug='macarons'), 4, 'You fold almond flour and sugar into whipped egg whites, pipe small rounds, rest them, and bake them.'),
((SELECT id FROM dishes WHERE slug='macarons'), 5, 'Two smooth almond meringue shells around ganache or jam, the French pastry shop''s showpiece.'),
((SELECT id FROM dishes WHERE slug='steak-frites'), 1, 'A brasserie order where you say how pink you want the meat.'),
((SELECT id FROM dishes WHERE slug='steak-frites'), 2, 'Belgium calls it a national dish and claims it first, while French brasseries treat it as theirs.'),
((SELECT id FROM dishes WHERE slug='steak-frites'), 3, 'Roland Barthes picked it apart in 1957 as a sign of being French.'),
((SELECT id FROM dishes WHERE slug='steak-frites'), 4, 'You pan-fry a rib-eye rare, deglaze the pan for sauce, and serve it beside twice-fried potato sticks.'),
((SELECT id FROM dishes WHERE slug='steak-frites'), 5, 'France''s bistro classic, a pan-seared rib-eye beside a heap of golden fries and béarnaise.'),
((SELECT id FROM dishes WHERE slug='profiteroles'), 1, 'Small hollow puffs piled up and drowned in warm chocolate sauce.'),
((SELECT id FROM dishes WHERE slug='profiteroles'), 2, 'A legend credits Catherine de'' Medici''s chef, but it dates from the 1800s, when Carême set the recipe.'),
((SELECT id FROM dishes WHERE slug='profiteroles'), 3, 'Glazed with caramel and stacked into a tower, they become the cake at French weddings and Christmas.'),
((SELECT id FROM dishes WHERE slug='profiteroles'), 4, 'You cook flour into boiling butter and water, beat in eggs, pipe small mounds, and bake them until hollow.'),
((SELECT id FROM dishes WHERE slug='profiteroles'), 5, 'Split cream puffs filled with cream or ice cream under a pour of chocolate, a French bistro dessert.'),
((SELECT id FROM dishes WHERE slug='moules-frites'), 1, 'A black iron pot set down with a second bowl for the empty shells.'),
((SELECT id FROM dishes WHERE slug='moules-frites'), 2, 'Flemish coast cooks paired cheap shellfish with winter fried potatoes; northern France disputes it.'),
((SELECT id FROM dishes WHERE slug='moules-frites'), 3, 'Lille''s huge September street fair is known for it, with diners leaving heaps of empty shells outside.'),
((SELECT id FROM dishes WHERE slug='moules-frites'), 4, 'You steam mussels open in white wine with shallots, butter and parsley, and fry potato sticks twice.'),
((SELECT id FROM dishes WHERE slug='moules-frites'), 5, 'Belgium''s national dish, a steaming pot of mussels in white wine with a cone of crisp fries.'),
((SELECT id FROM dishes WHERE slug='stroopwafel'), 1, 'A thin disc you rest on a hot cup of coffee until it goes soft.'),
((SELECT id FROM dishes WHERE slug='stroopwafel'), 2, 'Gouda bakers stuck leftover scraps together with syrup around 1800, and the town had 17 factories by 1960.'),
((SELECT id FROM dishes WHERE slug='stroopwafel'), 3, 'The filling is warm caramel syrup that sets as it cools, so it stretches into threads when you bite.'),
((SELECT id FROM dishes WHERE slug='stroopwafel'), 4, 'You press dough in a hot waffle iron, split each disc in half, and spread warm syrup between the halves.'),
((SELECT id FROM dishes WHERE slug='stroopwafel'), 5, 'Two thin crisp layers glued with caramel, the syrup waffle sold at Dutch markets.'),
((SELECT id FROM dishes WHERE slug='apple-strudel'), 1, 'A long golden roll dusted with sugar, sliced warm at a café counter.'),
((SELECT id FROM dishes WHERE slug='apple-strudel'), 2, 'Vienna''s city library holds a recipe from 1696, and the pastry spread through the Habsburg lands.'),
((SELECT id FROM dishes WHERE slug='apple-strudel'), 3, 'Bakers stretch the dough so thin you could read a newspaper through it.'),
((SELECT id FROM dishes WHERE slug='apple-strudel'), 4, 'You spread buttered breadcrumbs, raisins and cinnamon over the sheet with the filling, then roll it up and bake it.'),
((SELECT id FROM dishes WHERE slug='apple-strudel'), 5, 'Austria''s spiced fruit pastry, flaky spiral slices served warm with vanilla sauce or cream.'),
((SELECT id FROM dishes WHERE slug='sachertorte'), 1, 'A dark glossy slice with unsweetened whipped cream on the side.'),
((SELECT id FROM dishes WHERE slug='sachertorte'), 2, 'A teenage apprentice gets credit for baking it in 1832 for a prince, though he later gave other dates.'),
((SELECT id FROM dishes WHERE slug='sachertorte'), 3, 'A hotel and a pastry shop fought in court for decades over who could call theirs the original.'),
((SELECT id FROM dishes WHERE slug='sachertorte'), 4, 'You split a chocolate sponge, spread apricot jam on it, and pour over a chocolate glaze that sets firm.'),
((SELECT id FROM dishes WHERE slug='sachertorte'), 5, 'A chocolate cake with a thin streak of apricot under a shiny dark glaze, from Austria.'),
((SELECT id FROM dishes WHERE slug='gambas-al-ajillo'), 1, 'Brought out still spitting in a small clay dish.'),
((SELECT id FROM dishes WHERE slug='gambas-al-ajillo'), 2, 'Madrid gets the credit for it, and you''ll find it most in the center and north of the country.'),
((SELECT id FROM dishes WHERE slug='gambas-al-ajillo'), 3, 'The shrimp go in only at the last moment, so they finish cooking in the oil on the way to the table.'),
((SELECT id FROM dishes WHERE slug='gambas-al-ajillo'), 4, 'You fry sliced garlic and dried chili gently in lots of olive oil, then drop in peeled shrimp and parsley.'),
((SELECT id FROM dishes WHERE slug='gambas-al-ajillo'), 5, 'Spain''s garlic shrimp, sizzling in a pool of golden olive oil, a tapa eaten with wine.'),
((SELECT id FROM dishes WHERE slug='saganaki'), 1, 'Cheese fried until it crusts and bubbles, scooped up with bread.'),
((SELECT id FROM dishes WHERE slug='saganaki'), 2, 'A Chicago Greektown restaurant started setting it alight at the table in 1968, on a customer''s suggestion.'),
((SELECT id FROM dishes WHERE slug='saganaki'), 3, 'Waiters in North America shout ''opa!'' as the flames go up, then put them out with lemon.'),
((SELECT id FROM dishes WHERE slug='saganaki'), 4, 'You dust a thick slice of hard sheep''s milk cheese in flour and fry it in hot oil until it blisters.'),
((SELECT id FROM dishes WHERE slug='saganaki'), 5, 'Greece''s pan-fried cheese, named for the little pan it cooks in, golden and salty.'),
((SELECT id FROM dishes WHERE slug='chicken-kiev'), 1, 'Cut into it carefully, or hot butter squirts across the plate.'),
((SELECT id FROM dishes WHERE slug='chicken-kiev'), 2, 'Russian cooks adapted French stuffed cutlets in the 1800s; oral tradition credits one hotel kitchen.'),
((SELECT id FROM dishes WHERE slug='chicken-kiev'), 3, 'A British chain sold it as a ready meal from 1979, and some supermarkets changed its spelling in 2022.'),
((SELECT id FROM dishes WHERE slug='chicken-kiev'), 4, 'You pound a breast flat, roll it around cold herb butter, coat it in egg and crumbs, and fry it.'),
((SELECT id FROM dishes WHERE slug='chicken-kiev'), 5, 'A crumbed chicken roll bursting with garlic butter, named for the capital of Ukraine.'),
((SELECT id FROM dishes WHERE slug='paczki'), 1, 'Bought by the dozen on one day each winter, from a line out the door.'),
((SELECT id FROM dishes WHERE slug='paczki'), 2, 'Poles have fried them since the Middle Ages, and a French cook gets the credit for lightening the dough.'),
((SELECT id FROM dishes WHERE slug='paczki'), 3, 'Hamtramck, Michigan, holds a parade for them on Fat Tuesday, with eating contests.'),
((SELECT id FROM dishes WHERE slug='paczki'), 4, 'You add a splash of grain alcohol to a rich yeast dough so it drinks less oil, then fry it and fill it with jam.'),
((SELECT id FROM dishes WHERE slug='paczki'), 5, 'Poland''s Fat Thursday doughnuts, dense and jam-filled, topped with icing or candied orange peel.'),
((SELECT id FROM dishes WHERE slug='golabki'), 1, 'Fat green parcels lined up in a baking dish under tomato sauce.'),
((SELECT id FROM dishes WHERE slug='golabki'), 2, 'Poles set it out at weddings and Christmas, and neighbours from Ukraine to Sweden each have their own version.'),
((SELECT id FROM dishes WHERE slug='golabki'), 3, 'Americans with no Slavic grandmother still know it, under the plain name of stuffed cabbage.'),
((SELECT id FROM dishes WHERE slug='golabki'), 4, 'You wrap blanched cabbage leaves around minced beef, pork and rice, then bake them in tomato sauce.'),
((SELECT id FROM dishes WHERE slug='golabki'), 5, 'Cabbage rolls stuffed with meat and rice and braised in tomato, Poland''s ''little pigeons''.'),
((SELECT id FROM dishes WHERE slug='cevapi'), 1, 'Little finger-length sausages served in fives or tens.'),
((SELECT id FROM dishes WHERE slug='cevapi'), 2, 'Ottoman grill culture gave it its name, and no record shows it as its own dish before the 1850s.'),
((SELECT id FROM dishes WHERE slug='cevapi'), 3, 'Several Balkan countries claim it, and historians say many ''ancient'' local styles date from the 1960s.'),
((SELECT id FROM dishes WHERE slug='cevapi'), 4, 'You mix minced beef with salt, roll it into small fingers, and grill them over charcoal.'),
((SELECT id FROM dishes WHERE slug='cevapi'), 5, 'Grilled minced-meat fingers stuffed into soft flatbread with raw onion, a Bosnian national dish.'),
((SELECT id FROM dishes WHERE slug='aebleskiver'), 1, 'Fluffy golden balls turned in their pan with a knitting needle.'),
((SELECT id FROM dishes WHERE slug='aebleskiver'), 2, 'The word first shows up in an 1866 book of Christmas poems, though the recipe is older.'),
((SELECT id FROM dishes WHERE slug='aebleskiver'), 3, 'They come in a cast-iron pan of round wells, and the name promises a fruit that modern ones leave out.'),
((SELECT id FROM dishes WHERE slug='aebleskiver'), 4, 'You pour batter into the hollows of a hot pan and keep turning each ball with a skewer until it cooks through.'),
((SELECT id FROM dishes WHERE slug='aebleskiver'), 5, 'Denmark''s ''apple slices'', round pancake puffs eaten at Christmas with jam and mulled wine.'),
((SELECT id FROM dishes WHERE slug='shortbread'), 1, 'Pale, crumbly fingers that fall apart if you dunk too long.'),
((SELECT id FROM dishes WHERE slug='shortbread'), 2, 'Bakers made it as early as the 1100s, and the first printed recipe appeared in 1736.'),
((SELECT id FROM dishes WHERE slug='shortbread'), 3, 'Mary, Queen of Scots gets popular credit for refining it, though the evidence is thin.'),
((SELECT id FROM dishes WHERE slug='shortbread'), 4, 'You rub butter into flour and sugar at one part sugar, two butter, three flour, press it flat, and prick it.'),
((SELECT id FROM dishes WHERE slug='shortbread'), 5, 'Buttery biscuits cut into ''petticoat tails'', a Scottish Hogmanay tradition.');
